#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long p;
    cin >> n >> p;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long total = 0;
    for (int i = 0; i < n; i++) total += a[i];
    long long r = total % p;
    if (r == 0) {
        cout << 0 << "\n";
    } else {
        unordered_map<long long, int> last;
        last[0] = -1;
        long long cur = 0;
        int best = n;
        for (int j = 0; j < n; j++) {
            cur = (cur + a[j]) % p;
            long long need = ((cur - r) % p + p) % p;
            auto it = last.find(need);
            if (it != last.end()) best = min(best, j - it->second);
            last[cur] = j;
        }
        cout << (best < n ? best : -1) << "\n";
    }

    return 0;
}

