import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long p = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long total = 0;
        for (int i = 0; i < n; i++) total += a[i];
        long r = total % p;
        if (r == 0) {
            System.out.println(0);
        } else {
            Map<Long, Integer> last = new HashMap<>();
            last.put(0L, -1);
            long cur = 0;
            int best = (int) n;
            for (int j = 0; j < n; j++) {
                cur = (cur + a[j]) % p;
                long need = ((cur - r) % p + p) % p;
                Integer start = last.get(need);
                if (start != null) best = Math.min(best, j - start);
                last.put(cur, j);
            }
            System.out.println(best < n ? best : -1);
        }
    }
}
